import type { ReactNode } from "react"
import { Field, FieldContent, FieldDescription, FieldLabel } from "@/components/ui/field"
import { Checkbox } from "@/components/ui/checkbox"
import { Switch } from "@/components/ui/switch"
import { SETTINGS_BOOLEAN_CONTROL } from "./config"
import { cn } from "@/lib/utils"

type FieldProps = {
  id?: string
  label?: ReactNode
  help?: ReactNode
  disabled?: boolean
  className?: string
}

/** Shared presentation for schema fields and custom settings controls. */
export function SettingsControlField({ id, label, help, disabled, className, children }: FieldProps & { children: ReactNode }) {
  return (
    <Field orientation="vertical" data-disabled={disabled || undefined} className={className}>
      {label ? (
        <FieldLabel htmlFor={id} data-role="settings-input-label"
          className="text-[11px] leading-4 font-normal text-foreground/55">
          {label}
        </FieldLabel>
      ) : null}
      <FieldContent>
        {children}
        {help ? <FieldDescription>{help}</FieldDescription> : null}
      </FieldContent>
    </Field>
  )
}

/** Custom settings obey the same global checkbox/switch choice as SettingsForm. */
export function SettingsBooleanField({ id, label, help, disabled, className, checked, onCheckedChange, "aria-label": ariaLabel }: FieldProps & {
  id: string
  checked: boolean
  onCheckedChange: (checked: boolean) => void
  "aria-label"?: string
}) {
  if (SETTINGS_BOOLEAN_CONTROL === "checkbox") {
    return (
      <Field orientation="horizontal" data-disabled={disabled || undefined}
        className={cn("items-start justify-start gap-2", className)}>
        <Checkbox id={id} aria-label={ariaLabel} checked={checked} disabled={disabled} className="mt-0.5"
          onCheckedChange={state => onCheckedChange(state === true)} />
        <FieldContent className="translate-y-px">
          {label ? <FieldLabel htmlFor={id} className="font-normal">{label}</FieldLabel> : null}
          {help ? <FieldDescription>{help}</FieldDescription> : null}
        </FieldContent>
      </Field>
    )
  }
  return (
    <Field orientation="horizontal" data-disabled={disabled || undefined} className={className}>
      <FieldContent>
        {label ? <FieldLabel htmlFor={id}>{label}</FieldLabel> : null}
        {help ? <FieldDescription>{help}</FieldDescription> : null}
      </FieldContent>
      <Switch id={id} aria-label={ariaLabel} checked={checked} disabled={disabled} onCheckedChange={onCheckedChange} />
    </Field>
  )
}
